bind.getValue:
(el) => {
  const p = el.querySelector('.h5p-placeholder');
  return p && !p.hasAttribute('data-apuntes-pendiente') ? p.textContent.trim() : '';
}

bind.setValue:
(el, v) => {
  const p = el.querySelector('.h5p-placeholder');
  if (!p) { return; }
  if (v) { p.textContent = v; p.removeAttribute('data-apuntes-pendiente'); }
  else { p.textContent = 'H5P pendiente: pulsa este recuadro y después el botón H5P del editor'; p.setAttribute('data-apuntes-pendiente', '1'); }
}
